#!/usr/bin/env python3
# SPDX-License-Identifier: AGPL-3.0-or-later
"""Regenerate meshtastic_device.json and src/meshtastic_enums.rs.

Every frame is encoded by the upstream reference library (meshtastic python protobufs), the same library that
decodes it in the checks below; the expectations are what that library says, never this repo's decoder.
Provenance: "reference-encoded". Nothing here was recorded off the air.
Needs: pip install meshtastic pyserial pyyaml tabulate requests pypubsub. Run from this directory.
"""
import json, struct, pathlib
from meshtastic.protobuf import mesh_pb2, config_pb2, admin_pb2, channel_pb2, portnums_pb2

def fr(**kw):
    m = mesh_pb2.FromRadio(); m.id = 1
    for k, v in kw.items():
        getattr(m, k).CopyFrom(v)
    return m.SerializeToString()

NODE = 0xA1B2C3D4
out = {"provenance": "reference-encoded (meshtastic python protobufs)", "node": "!a1b2c3d4", "frames": []}
def add(name, raw): out["frames"].append({"name": name, "hex": raw.hex()})

mi = mesh_pb2.MyNodeInfo(my_node_num=NODE); add("my_info", fr(my_info=mi))
md = mesh_pb2.DeviceMetadata(firmware_version="2.7.15.567b8ea", hw_model=mesh_pb2.HardwareModel.HELTEC_V3,
                             role=config_pb2.Config.DeviceConfig.CLIENT, hasBluetooth=True, hasWifi=True)
add("metadata", fr(metadata=md))
ni = mesh_pb2.NodeInfo(num=NODE, user=mesh_pb2.User(id="!a1b2c3d4", long_name="Jay Heltec", short_name="JH",
                       hw_model=mesh_pb2.HardwareModel.HELTEC_V3))
add("node_info_self", fr(node_info=ni))
c = config_pb2.Config(); c.lora.use_preset = True; c.lora.modem_preset = config_pb2.Config.LoRaConfig.LONG_FAST
c.lora.region = config_pb2.Config.LoRaConfig.EU_868; c.lora.hop_limit = 3; c.lora.tx_enabled = True; c.lora.tx_power = 14
c.lora.channel_num = 0
add("config_lora", fr(config=c))
c = config_pb2.Config(); c.device.role = config_pb2.Config.DeviceConfig.CLIENT; c.device.node_info_broadcast_secs = 10800
add("config_device", fr(config=c))
c = config_pb2.Config(); c.position.position_broadcast_secs = 900; c.position.gps_update_interval = 30
add("config_position", fr(config=c))
ch0 = channel_pb2.Channel(index=0, role=channel_pb2.Channel.PRIMARY); ch0.settings.psk = bytes([1]); ch0.settings.name = ""
add("channel_0", fr(channel=ch0))
ch1 = channel_pb2.Channel(index=1, role=channel_pb2.Channel.SECONDARY); ch1.settings.psk = bytes(range(1, 33)); ch1.settings.name = "family"
ch1.settings.uplink_enabled = True
add("channel_1", fr(channel=ch1))
ch2 = channel_pb2.Channel(index=2, role=channel_pb2.Channel.DISABLED)
add("channel_2", fr(channel=ch2))
cc = mesh_pb2.FromRadio(); cc.id = 2; cc.config_complete_id = 0x7a050001; add("config_complete", cc.SerializeToString())

# the writes the app asks for, encoded by the reference library (ToRadio wrapped, unframed)
def toradio_admin(adm, to=NODE, pid=0x11223344):
    pkt = mesh_pb2.MeshPacket(); setattr(pkt, "to", to); pkt.id = pid
    pkt.decoded.portnum = portnums_pb2.ADMIN_APP; pkt.decoded.payload = adm.SerializeToString(); pkt.decoded.want_response = False
    pkt.priority = mesh_pb2.MeshPacket.RELIABLE   # what the reference client sets for admin
    tr = mesh_pb2.ToRadio(packet=pkt); return tr.SerializeToString()
w = {}
a = admin_pb2.AdminMessage(begin_edit_settings=True); w["begin"] = toradio_admin(a).hex()
a = admin_pb2.AdminMessage(commit_edit_settings=True); w["commit"] = toradio_admin(a).hex()
a = admin_pb2.AdminMessage(); a.set_config.lora.use_preset = True; a.set_config.lora.modem_preset = config_pb2.Config.LoRaConfig.MEDIUM_FAST
a.set_config.lora.region = config_pb2.Config.LoRaConfig.US; a.set_config.lora.hop_limit = 3; a.set_config.lora.tx_enabled = True
a.set_config.lora.tx_power = 14; a.set_config.lora.channel_num = 0
w["set_lora_us_mediumfast"] = toradio_admin(a).hex()
a = admin_pb2.AdminMessage(); a.set_owner.long_name = "Trail Radio"; a.set_owner.short_name = "TR"
w["set_owner"] = toradio_admin(a).hex()
a = admin_pb2.AdminMessage(); a.set_channel.index = 1; a.set_channel.role = channel_pb2.Channel.SECONDARY
a.set_channel.settings.psk = bytes(range(1, 33)); a.set_channel.settings.name = "crew"; a.set_channel.settings.uplink_enabled = True
w["set_channel_1_name_crew"] = toradio_admin(a).hex()
out["writes"] = w
pathlib.Path("meshtastic_device.json").write_text(json.dumps(out, indent=1) + "\n")

# enum tables for the settings screens
def names(enum): return [(v.number, v.name) for v in enum.DESCRIPTOR.values]
region = names(config_pb2.Config.LoRaConfig.RegionCode); preset = names(config_pb2.Config.LoRaConfig.ModemPreset)
role = names(config_pb2.Config.DeviceConfig.Role); hw = names(mesh_pb2.HardwareModel)
def tbl(n, items): return f"pub const {n}: &[(u32, &str)] = &[\n" + "".join(f'    ({k}, "{v}"),\n' for k, v in items) + "];\n"
src = "// SPDX-License-Identifier: AGPL-3.0-or-later\n// Generated by tests/fixtures/gen_device_fixtures.py from the meshtastic protobufs (GPL-3.0). Do not edit.\n"
src += tbl("REGIONS", region) + tbl("MODEM_PRESETS", preset) + tbl("ROLES", role) + tbl("HW_MODELS", hw)
pathlib.Path("../../src/meshtastic_enums.rs").write_text(src)
